/* ================= \u4E3B\u9898\u76AE\u80A4\u6846\u67B6\uFF08data-skin\uFF09 =================
   \u65B0\u589E\u76AE\u80A4\uFF1A\u2460 Config \u7684 theme union \u52A0 id\uFF1B\u2461 \u8FD9\u91CC\u52A0 [data-skin="id"] \u53D8\u91CF + \u5C11\u91CF\u8868\u9762\u8986\u76D6\uFF1B
   \u2462 client \u7684 SKINS \u5217\u8868\u52A0\u4E00\u9879\uFF08name/desc/\u4E09\u8272\u9884\u89C8\uFF09\u3002\u6240\u6709\u9875\u9762\u5171\u7528\u540C\u4E00\u5957\u53D8\u91CF\u3002 */
